<script setup lang="ts">
import CollaborationCell from '@/views/collaboration/components/CollaborationCell.vue'
import {phoneMemberName} from '@/utils/phoneMembers'
import {phoneSetCompatibilities,withPhoneSetCompatibilities} from '@/utils/phoneCompatibility'
import type {CompatiblePhone,CompatiblePhoneRelation} from '@/types/molds'
import type {PhoneSetCompatibility} from '@/types/collaboration'
const props=defineProps<{relations:CompatiblePhoneRelation[];members:CompatiblePhone[];sets:{moldSetId:number;assetNumber:string;setNo:number;masterDataStatus?:'active'|'inactive'}[];editable:boolean;dirty:boolean}>()
const emit=defineEmits<{update:[phoneModelId:number,changes:Partial<CompatiblePhoneRelation>]}>()
const evidenceField=(part:string)=>({key:part+'Evidence',label:part.toUpperCase()+' 本套适配确认依据',kind:'text',group:'engineering' as const,maxLength:2000})
function label(id:number){const phone=props.members.find(p=>p.phoneModelId===id);return phone?phoneMemberName(phone):`手机资料 #${id}`}
function setLabel(id:number){const set=props.sets.find(s=>s.moldSetId===id);return set?`${set.assetNumber} · 第 ${set.setNo} 套${set.masterDataStatus==='inactive'?'（已停用）':''}`:`实物套 #${id}`}
function update(relation:CompatiblePhoneRelation,sets:PhoneSetCompatibility[]){emit('update',relation.phoneModelId,withPhoneSetCompatibilities(relation,sets))}
function selectSets(relation:CompatiblePhoneRelation,ids:number[]){const current=phoneSetCompatibilities(relation);update(relation,[...new Set(ids)].sort((a,b)=>a-b).map(id=>current.find(s=>s.moldSetId===id)||{moldSetId:id,pcConfirmed:false,tpuConfirmed:false,pcEvidence:null,tpuEvidence:null}))}
function changeSet(relation:CompatiblePhoneRelation,id:number,patch:Partial<PhoneSetCompatibility>){update(relation,phoneSetCompatibilities(relation).map(s=>s.moldSetId===id?{...s,...patch}:s))}
</script>
<template><div class="relations"><section v-for="relation in relations" :key="relation.phoneModelId" class="phone-relation"><header><strong>{{label(relation.phoneModelId)}}</strong><span>每套分别核对 PC、TPU，保留部分适配与部件依据。</span></header><label><span>适用实物套</span><el-select :model-value="phoneSetCompatibilities(relation).map(s=>s.moldSetId)" multiple :disabled="!editable" @update:model-value="selectSets(relation,$event)"><el-option v-for="s in sets" :key="s.moldSetId" :value="s.moldSetId" :label="setLabel(s.moldSetId)" :disabled="s.masterDataStatus==='inactive'&&!phoneSetCompatibilities(relation).some(current=>current.moldSetId===s.moldSetId)"/></el-select></label><article v-for="set in phoneSetCompatibilities(relation)" :key="set.moldSetId" class="set-compatibility" :data-mold-set-id="set.moldSetId"><strong>{{setLabel(set.moldSetId)}}</strong><div class="part-checks"><section v-for="part in (['pc','tpu'] as const)" :key="part"><el-checkbox :model-value="set[part+'Confirmed' as 'pcConfirmed'|'tpuConfirmed']" :disabled="!editable" @change="changeSet(relation,set.moldSetId,{[part+'Confirmed']:!!$event})">{{part.toUpperCase()}} 模具适配已核对</el-checkbox><label><span>{{part.toUpperCase()}} 本套适配确认依据</span><CollaborationCell :field="evidenceField(part)" :value="set[part+'Evidence' as 'pcEvidence'|'tpuEvidence']" :editable="editable" :dirty="dirty" @preview="changeSet(relation,set.moldSetId,{[part+'Evidence']:$event})" @edit="changeSet(relation,set.moldSetId,{[part+'Evidence']:$event})"/></label></section></div><p v-if="!set.pcConfirmed||!set.tpuConfirmed||!set.pcEvidence?.trim()||!set.tpuEvidence?.trim()" class="hint">本套适配未完整确认；可以保存已核对的部件，其余保留待核对。</p></article><p class="hint">添加关系不创建实物、不改刻码、不复制费用。</p></section></div></template>
<style scoped>.relations{display:grid;gap:12px}.phone-relation{padding:12px;border:1px solid #dfe6ef;border-radius:4px;background:#fbfcfe}.phone-relation header{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.phone-relation header span,.hint{font-size:12px;color:#7b8999;line-height:1.5}.phone-relation label{display:block;min-width:0;margin:8px 0}.phone-relation label>span{display:block;margin-bottom:5px;color:#294f75;font-weight:600}.el-select{width:100%}.part-checks{display:grid;grid-template-columns:minmax(0,1fr);gap:12px}.set-compatibility{margin-top:8px;padding:8px;border:1px solid #e2e8f0;background:#fff}.phone-relation :deep(.el-tag){height:auto;white-space:normal}.phone-relation :deep(.el-tag__content){white-space:normal;line-height:1.5}@media(max-width:760px){.part-checks{grid-template-columns:1fr}}.phone-relation :deep(.readonly-value){display:block;white-space:pre-wrap;overflow:visible;-webkit-line-clamp:unset}.phone-relation :deep(textarea){white-space:pre-wrap;overflow-wrap:anywhere;resize:vertical;min-height:60px}</style>
